export default class PrintessProductionService extends Shopware.Classes.ApiService {
    constructor(httpClient, loginService, apiEndpoint = 'printess') {
        super(httpClient, loginService, apiEndpoint);
        this.name = 'printessProductionService';
    }

    approveLineItem(orderId, lineItemId) {
        return this.httpClient
            .post(`/_action/printess/orders/${orderId}/line-items/${lineItemId}/approve`, {}, { headers: this.getBasicHeaders() })
            .then((response) => Shopware.Classes.ApiService.handleResponse(response));
    }

    checkLineItemStatus(orderId, lineItemId) {
        return this.httpClient
            .post(`/_action/printess/orders/${orderId}/line-items/${lineItemId}/check-status`, {}, { headers: this.getBasicHeaders() })
            .then((response) => Shopware.Classes.ApiService.handleResponse(response));
    }

    restartLineItem(orderId, lineItemId) {
        return this.httpClient
            .post(`/_action/printess/orders/${orderId}/line-items/${lineItemId}/restart`, {}, { headers: this.getBasicHeaders() })
            .then((response) => Shopware.Classes.ApiService.handleResponse(response));
    }
}
